import{_ as o,l as n,o as a,c as s,v as t,p as l,x as i,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"流水线五级","description":"","frontmatter":{"title":"流水线五级","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pipeline-five-stage.md","filePath":"cs/pipeline-five-stage.md","lastUpdated":1789023840000}'),h={name:"cs/pipeline-five-stage.md"};function _(f,e,m,E,u,I){const r=n("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="流水线五级" tabindex="-1">流水线五级 <a class="header-anchor" href="#流水线五级" aria-label="Permalink to &quot;流水线五级&quot;">​</a></h1><div class="epigraph"><p>把一条指令切成可重叠的几段，时钟只需覆盖最慢的一段，吞吐才不再被整条组合路径绑架。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/privilege-rings">上一课</a>把异常入口收进特权级：用户态不能直接碰 CSR 和页表。<a href="/cs/privilege-rings">单周期数据通路</a>已经能在一个时钟里跑完一条 RISC-V 整数指令，<a href="/cs/multicycle-microcode">多周期与微程序直觉</a>已经承认可以把取指、译码、执行拆开。本课不重画 ALU，也不从「处理器是什么」另起。缺口是：单周期的时钟被最长路径钉死；多周期解放了周期，却把功能单元闲置。本课只把通路切成五级并重叠。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单周期里，取指令存储器、寄存器堆、ALU、数据存储器必须在同一拍内稳定。时钟周期等于这条最长组合路径，简单的 <code>addi</code> 也得等 load 走完。多周期让不同指令占用不同拍，平均 CPI 大于 1，吞吐上不去。缺口不是新的 ISA，而是<strong>同时让多条指令分别占用通路的不同段</strong>。</p><p>RISC-V 整数指令可以切成取指、译码/读寄存器、执行/有效地址、访存、写回。本课只钉这五级；冒险、转发、分支预测都是后课留下的缺口。</p><p><span class="marginnote">经典五级是 COD 教学机的骨架，不是当代乱序核的流水线深度。后课超标量会加宽，本课先把重叠说清。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在相邻级之间插入流水线寄存器，锁存本级要交给下级的 PC、指令字、操作数、ALU 结果和控制信号。理想情况下每个时钟推进一级：第五拍起，每拍提交一条指令，吞吐接近每拍一条，而单条指令的延迟仍是五拍。</p>',9)),(a(),l(c,null,{default:i(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20IF%5B%22IF%20%E5%8F%96%E6%8C%87%22%5D%20--%3E%20ID%5B%22ID%20%E8%AF%91%E7%A0%81%22%5D%0A%20%20ID%20--%3E%20EX%5B%22EX%20%E6%89%A7%E8%A1%8C%22%5D%0A%20%20EX%20--%3E%20MEM%5B%22MEM%20%E8%AE%BF%E5%AD%98%22%5D%0A%20%20MEM%20--%3E%20WB%5B%22WB%20%E5%86%99%E5%9B%9E%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>控制仍来自<a href="/cs/control-truth-table">控制器真值表</a>，只是信号随指令在寄存器里向后传，而不是在一拍里驱动整条通路。本课假定指令存储器与数据存储器暂时可同时访问；做不到时就是下一课的结构冒险。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>重叠改变的是利用率，不是指令语义。程序员仍看见顺序 ISA：<a href="/cs/register-file">寄存器堆</a>的写回发生在 WB，读发生在 ID。理想 CPI 从单周期的 1 变成「渐近 1」，时钟频率却可以按级内延迟提高。加速来自吞吐，不来自把加法算得更快。</p><p>五级是对 RISC-V 整数核的划分：load/store 需要 MEM，算术指令在 EX 已出结果，分支的目标与条件也在 EX 才齐。划分本身会制造后课要处理的相关：后指令在 ID 读寄存器时，前指令可能还没写回。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入停顿、转发或分支预测，也不处理浮点或多周期运算。异常在<a href="/cs/exception-interrupt-entry">异常与中断入口</a>已有入口约定，流水线里同时有多条指令时「哪一条的 PC 算异常」是<a href="/cs/pipeline-exception">流水线异常</a>的缺口。特权级规则不变：流水线不额外授权。</p><p>后课默认：谈到经典流水线，指 IF/ID/EX/MEM/WB 与级间寄存器。理想吞吐每拍一条，尚未计入冒险。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单周期被最长路径卡住；五级重叠把时钟收到最慢的一段。</li><li>理想情况下第五拍起每拍完成一条，CPI 渐近为 1。</li><li>冒险、转发、异常精确性都是后课的缺口。</li><li>出处：Patterson and Hennessy, <em>Computer Organization and Design</em> RISC-V 版流水线章。</li></ul>',9))])}const g=o(h,[["render",_]]);export{C as __pageData,g as default};
